const pairKey=(a,b)=>[a,b].sort().join("-");
const frFind=(a,b)=>db.fr.find(f=>(f.a===a&&f.b===b)||(f.a===b&&f.b===a));
const friendsFor=u=>db.fr.filter(f=>f.a===u||f.b===u).map(f=>({id:f.a===u?f.b:f.a,st:f.st==="f"?"f":f.a===u?"out":"in"}));
